INSERT IGNORE INTO `tributes` (`id`, `unknown`, `name`, `descr`, `isguild`) VALUES
(60, 10, 'Aura of Preservation', '<p>The most skilled magicians enhance your mana preservation abilities.</p><p>Tier 1 - AC 15, Mana Preservation I</p><p>Tier 2 - AC 20, Mana Preservation II</p><p>Tier 3 - AC 25, Mana Preservation III</p><p>Tier 4 - AC 30, Mana Preservation IV</p><p>Tier 5 - AC 35, Mana Preservation V</p><p>Tier 6 - AC 40, Mana Preservation VI</p><p>Tier 7 - AC 45, Mana Preservation VII</p><p>Tier 8 - AC 50, Mana Preservation VIII</p><p>Tier 9 - AC 55, Mana Preservation IX</p><p>Tier 10 - AC 60, Mana Preservation X</p>', 1),
(61, 10, 'Commanding Presence', '<p>With this mighty elixir, you will be granted the power of faster summoning.</p><p>Tier 1 - Summoning Haste I</p><p>Tier 2 - Summoning Haste II</p><p>Tier 3 - Summoning Haste III</p><p>Tier 4 - Summoning Haste IV</p><p>Tier 5 - Summoning Haste V</p><p>Tier 6 - Summoning Haste VI</p><p>Tier 7 - Summoning Haste VII</p><p>Tier 8 - Summoning Haste VIII</p><p>Tier 9 - Summoning Haste IX</p><p>Tier 10 - Summoning Haste X</p>', 1),
(62, 8, 'Elemental Shield', '<p>Place an aura of protection against cold and fire.</p><p>Tier 1 - sv cold +5 and sv fire +5</p><p>Tier 2 - sv cold +10 and sv fire +10</p><p>Tier 3 - sv cold +15 and sv fire +15</p><p>Tier 4 - sv cold +20 and sv fire +20</p><p>Tier 5 - sv cold +25 and sv fire +25</p><p>Tier 6 - sv cold +30 and sv fire +30</p><p>Tier 7 - sv cold +35 and sv fire +35</p><p>Tier 8 - sv cold +40 and sv fire +40</p>', 1),
(63, 8, 'Essence of Perfection', '<p>Enhnace your base stats</p><p>Tier 1 - STR: +2 DEX: +2 STA: +2 CHA: +2 WIS: +2 INT: +2 AGI: +2 I</p><p>Tier 2 - STR: +4 DEX: +4 STA: +4 CHA: +4 WIS: +4 INT: +4 AGI: +4</p><p>Tier 3 - STR: +6 DEX: +6 STA: +6 CHA: +6 WIS: +6 INT: +6 AGI: +6</p><p>Tier 4 - STR: +8 DEX: +8 STA: +8 CHA: +8 WIS: +8 INT: +8 AGI: +8</p><p>Tier 5 - STR: +10 DEX: +10 STA: +10 CHA: +10 WIS: +10 INT: +10 AGI: +10</p><p>Tier 6 - STR: +12 DEX: +12 STA: +12 CHA: +12 WIS: +12 INT: +12 AGI: +12</p><p>Tier 7 - STR: +14 DEX: +14 STA: +14 CHA: +14 WIS: +14 INT: +14 AGI: +14</p><p>Tier 8 - STR: +16 DEX: +16 STA: +16 CHA: +16 WIS: +16 INT: +16 AGI: +16</p>', 1),
(64, 8, 'Ethereal Preservation', '<p>Enhnace your magic resistance.</p><p>Tier 1 - sv magic +15</p><p>Tier 2 - sv magic +20</p><p>Tier 3 - sv magic +25</p><p>Tier 4 - sv magic +30</p><p>Tier 5 - sv magic +35</p><p>Tier 6 - sv magic +40</p><p>Tier 7 - sv magic +45</p><p>Tier 8 - sv magic +50</p>', 1),
(65, 10, 'Expeditious Aid', '<p>Increases the haste at which spells cast.</p><p>Tier 1 - Enhancement Haste I</p><p>Tier 2 - Enhancement Haste II</p><p>Tier 3 - Enhancement Haste III</p><p>Tier 4 - Enhancement Haste IV</p><p>Tier 5 - Enhancement Haste V</p><p>Tier 6 - Enhancement Haste VI</p><p>Tier 7 - Enhancement Haste VII</p><p>Tier 8 - Enhancement Haste VIII</p><p>Tier 9 - Enhancement Haste IX</p><p>Tier 10 - Enhancement Haste X</p>', 1),
(66, 10, 'Frency of Conquest', ' <p>You party members enter a state of frenzy</p><p>Tier 1 - Attack +4, Improve All Damage I, Percussion Resonance 2</p><p>Tier 2 - Attack +6, Improve All Damage II, Percussion Resonance 4</p><p>Tier 3 - Attack +8, Improve All Damage III, Percussion Resonance 6</p><p>Tier 4 - Attack +10, Improve All Damage IV, Percussion Resonance 6</p><p>Tier 5 - Attack +50, Improve All Damage V, Percussion Resonance 6</p><p>Tier 6 - Attack +75, Improve All Damage VI, Percussion Resonance 6</p><p>Tier 7 - Attack +90, Improve All Damage VII, Percussion Resonance 6</p><p>Tier 8 - Attack +105, Improve All Damage VIII, Percussion Resonance 6</p><p>Tier 9 - Attack +120, Improve All Damage IX, Percussion Resonance 6</p><p>Tier 10 - Attack +120, Improve All Damage X, Percussion Resonance 6</p>', 1),
(67, 1, 'Gift of the Enchanter', 'You party is granted See Invisible, Ultravision, and Water Breating', 1),
(68, 10, 'Harmony of Essence', '<p>Increase the parties health, mana and endurance.</p><p>Tier 1 - Health +20 Mana +20 Endurance +20</p><p>Tier 2 - Health +50 Mana +50 Endurance +50</p><p>Tier 3 - Health +70 Mana +70 Endurance +70</p><p>Tier 4 - Health +100 Mana +100 Endurance +100</p><p>Tier 5 - Health +150 Mana +150 Endurance +150</p><p>Tier 6 - Health +200 Mana +200 Endurance +200</p><p>Tier 7 - Health +250 Mana +250 Endurance +250</p><p>Tier 8 - Health +300 Mana +300 Endurance +300</p><p>Tier 9 - Health +350 Mana +350 Endurance +350 Improved Damage IX</p><p>Tier 10 - Health +500 Mana +500 Endurance +500</p>', 1),
(69, 10, 'Peristent Boon', '<p>Extendes enhancement spells.</p><p>Tier 1 - Extended Enhancement I</p><p>Tier 2 - Extended Enhancement II</p><p>Tier 3 - Extended Enhancement III</p><p>Tier 4 - Extended Enhancement IV</p><p>Tier 5 - Extended Enhancement V</p><p>Tier 6 - Extended Enhancement VI</p><p>Tier 7 - Extended Enhancement VII</p><p>Tier 8 - Extended Enhancement VIII</p><p>Tier 9 - Extended Enhancement IX</p><p>Tier 10 - Extended Enhancement X</p>', 1),
(70, 10, 'Power of Alacrity', '<p>You feel as though you become more aware of magic and have been granted magic swiftness.</p><p>Tier 1 - Spell Haste I</p><p>Tier 2 - Spell Haste II</p><p>Tier 3 - Spell Haste III</p><p>Tier 4 - Spell Haste IV</p><p>Tier 5 - Spell Haste V</p><p>Tier 6 - Spell Haste VI</p><p>Tier 7 - Spell Haste VII</p><p>Tier 8 - Spell Haste VIII</p><p>Tier 9 - Spell Haste IX</p><p>Tier 10 - Spell Haste X</p>', 1),
(71, 10, 'Power of Conservation', '<p>With this mighty elixir, you will be granted the power of mana conservation.</p><p>Tier 1 - Mana Preservation I</p><p>Tier 2 - Mana Preservation II</p><p>Tier 3 - Mana Preservation III</p><p>Tier 4 - Mana Preservation IV</p><p>Tier 5 - Mana Preservation V</p><p>Tier 6 - Mana Preservation VI</p><p>Tier 7 - Mana Preservation VII</p><p>Tier 8 - Mana Preservation VIII</p><p>Tier 9 - Mana Preservation IX</p><p>Tier 10 - Mana Preservation X</p>', 1),
(72, 10, 'Power of Recovery', '<p>With this mighty elixir, you will be granted the power of faster casting recovery.</p><p>Tier 1 - Improved Healing I</p><p>Tier 2 - Improved Healing II</p><p>Tier 3 - Improved Healing III</p><p>Tier 4 - Improved Healing IV</p><p>Tier 5 - Improved Healing V</p><p>Tier 6 - Improved Healing VI</p><p>Tier 7 - Improved Healing VII</p><p>Tier 8 - Improved Healing VIII</p><p>Tier 9 - Improved Healing IX</p><p>Tier 10 - Improved Healing X</p>', 1),
(73, 10, 'Power of Sight', '<p>The gods focus your visual awareness allowing you to target at greater distances.</p><p>Tier 1 - Extended Range I</p><p>Tier 2 - Extended Range II</p><p>Tier 3 - Extended Range III</p><p>Tier 4 - Extended Range IV</p><p>Tier 5 - Extended Range V</p><p>Tier 6 - Extended Range VI</p><p>Tier 7 - Extended Range VII</p><p>Tier 8 - Extended Range VIII</p><p>Tier 9 - Extended Range IX</p><p>Tier 10 - Extended Range X</p>', 1),
(74, 10, 'Power of Suffering', '<p>The curse of suffering increases the torture of your foe.</p><p>Tier 1 - Burning Affliction I</p><p>Tier 2 - Burning Affliction II</p><p>Tier 3 - Burning Affliction III</p><p>Tier 4 - Burning Affliction IV</p><p>Tier 5 - Burning Affliction V</p><p>Tier 6 - Burning Affliction VI</p><p>Tier 7 - Burning Affliction VII</p><p>Tier 8 - Burning Affliction VIII</p><p>Tier 9 - Burning Affliction IX</p><p>Tier 10 - Burning Affliction X</p>', 1),
(75, 10, 'Power of Will', '<p>You master the skill of focus, creating more damage for your magical abilities.</p><p>Tier 1 - Improved Damage I</p><p>Tier 2 - Improved Damage II</p><p>Tier 3 - Improved Damage III</p><p>Tier 4 - Improved Damage IV</p><p>Tier 5 - Improved Damage V</p><p>Tier 6 - Improved Damage VI</p><p>Tier 7 - Improved Damage VII</p><p>Tier 8 - Improved Damage VIII</p><p>Tier 9 - Improved Damage IX</p><p>Tier 10 - Improved Damage X</p>', 1),
(76, 8, 'Purity', '<p>The clerics bestow protection against disease and poisons.</p><p>Tier 1 - sv disease +5 and sv poison +5</p><p>Tier 2 - sv disease +10 and sv poison +10</p><p>Tier 3 - sv disease +15 and sv poison +15</p><p>Tier 4 - sv disease +20 and sv poison +20</p><p>Tier 5 - sv disease +25 and sv poison +25</p><p>Tier 6 - sv disease +30 and sv poison +30</p><p>Tier 7 - sv disease +35 and sv poison +35</p><p>Tier 8 - sv disease +40 and sv poison +40</p>', 1),
(77, 10, 'Spiritual Alacrity', '<p>The speed of velious enters your mind and hands.</p><p>Tier 1 - Haste +21% and Spell Haste I</p><p>Tier 2 - Haste +31% and Spell Haste II</p><p>Tier 3 - Haste +36% and Spell Haste III</p><p>Tier 4 - Haste +41% and Spell Haste IV</p><p>Tier 5 - Haste +46% and Spell Haste V</p><p>Tier 6 - Haste +46% and Spell Haste VI</p><p>Tier 7 - Haste +46% and Spell Haste VII</p><p>Tier 8 - Haste +46% and Spell Haste VIII</p><p>Tier 9 - Haste +46% and Spell Haste IX</p><p>Tier 10 - Haste +46% and Spell Haste X</p>', 1),
(78, 5, 'Swift Arms', '<p>The speed of the feline enters your physical body.</p><p>Tier 1 - Haste +21%</p><p>Tier 2 - Haste +26%</p><p>Tier 3 - Haste +31%</p><p>Tier 4 - Haste +36%</p><p>Tier 5 - Haste +41%</p>', 1),
(79, 10, 'Symphony of Replenishment', '<p>Creates a delicate sound that enhances for health, mana and string abilities.</p><p>Tier 1 - Health Regen +2, Mana Regen +1 and String Resonance I</p><p>Tier 2 - Health Regen +4, Mana Regen +2 and String Resonance II</p><p>Tier 3 - Health Regen +6, Mana Regen +3 and String Resonance III</p><p>Tier 4 - Health Regen +8, Mana Regen +4 and String Resonance IV</p><p>Tier 5 - Health Regen +10, Mana Regen +5 and String Resonance V</p><p>Tier 6 - Health Regen +12, Mana Regen +6 and String Resonance VI</p><p>Tier 7 - Health Regen +14, Mana Regen +7 and String Resonance VII</p><p>Tier 8 - Health Regen +16, Mana Regen +8 and String Resonance VIII</p><p>Tier 9 - Health Regen +18, Mana Regen +9 and String Resonance IX</p><p>Tier 10 - Health Regen +20, Mana Regen +10 and String Resonance X</p>', 1),
(80, 10, 'Twinge of Pain', '<p>Your magical swiftness increases.</p><p>Tier 1 - Affliction Haste I</p><p>Tier 2 - Affliction Haste II</p><p>Tier 3 - Affliction Haste III</p><p>Tier 4 - Affliction Haste IV</p><p>Tier 5 - Affliction Haste V</p><p>Tier 6 - Affliction Haste VI</p><p>Tier 7 - Affliction Haste VII</p><p>Tier 8 - Affliction Haste VIII</p><p>Tier 9 - Affliction Haste IX</p><p>Tier 10 - Affliction Haste X</p>', 1),
(81, 10, 'Visions of Command', '<p>The creation of magical objects is enhanced.</p><p>Tier 1 - Summoning Efficiency I</p><p>Tier 2 - Summoning Efficiency II</p><p>Tier 3 - Summoning Efficiency III</p><p>Tier 4 - Summoning Efficiency IV</p><p>Tier 5 - Summoning Efficiency V</p><p>Tier 6 - Summoning Efficiency VI</p><p>Tier 7 - Summoning Efficiency VII</p><p>Tier 8 - Summoning Efficiency VIII</p><p>Tier 9 - Summoning Efficiency IX</p><p>Tier 10 - Summoning Efficiency X</p>', 1),
(82, 10, 'Visions of Suffering', '<p>You master the skill of concentration, using less mana for certain spells.</p><p>Tier 1 - Affliction Efficiency I</p><p>Tier 2 - Affliction Efficiency II</p><p>Tier 3 - Affliction Efficiency III</p><p>Tier 4 - Affliction Efficiency IV</p><p>Tier 5 - Affliction Efficiency V</p><p>Tier 6 - Affliction Efficiency VI</p><p>Tier 7 - Affliction Efficiency VII</p><p>Tier 8 - Affliction Efficiency VIII</p><p>Tier 9 - Affliction Efficiency IX</p><p>Tier 10 - Affliction Efficiency X</p>', 1);
